const titleFor = (value:string) => value.replace(/-/g," ").replace(/\b\w/g, c=>c.toUpperCase());

function liveRouteCards(a: Answers, all: Pathway[]): Pathway[] {
 const t=[...a.subjects,...a.interests,a.stream].join(" ").toLowerCase();
 const patterns: [RegExp,string[]][]=[
  [/computer|digital|science-maths|maths|build/i,["btech-cse","btech-it","btech-aids","btech-ece","computer-science","bca"]],
  [/commerce|business|organise/i,["bcom","bba","chartered-accountancy","economics","finance"]],
  [/biology|science-biology|health/i,["medicine","nursing","pharmacy","physiotherapy","biotechnology"]],
  [/creative|design|art|fashion/i,["design","fashion","animation","architecture","journalism"]],
  [/people|help|writing|arts/i,["psychology","law","teaching","social-work","journalism"]],
  [/nature|field|hands-on|vocational/i,["agriculture","environment","mechanical","civil","iti"]]
 ];
 const ids=patterns.filter(([re])=>re.test(t)).flatMap(([,ids])=>ids);
 let found=ids.map(id=>all.find(p=>p.id===id||p.title.toLowerCase().includes(id.replace(/-/g," ")))).filter(Boolean) as Pathway[];
 if(a.stream==="science-maths") found=[...all.filter(p=>/engineering|computer|technology|data/i.test(p.field+" "+p.title)),...found];
 if(a.stream==="commerce") found=[...all.filter(p=>/commerce|business|finance|account|econom/i.test(p.field+" "+p.title)),...found];
 if(a.stream==="science-biology") found=[...all.filter(p=>/health|biology|medical|nursing|pharmacy/i.test(p.field+" "+p.title)),...found];
 const unique=found.filter((p,i,arr)=>arr.findIndex(q=>q.id===p.id)===i);
 return (unique.length?unique:all.slice(0,6)).slice(0,4);
}
function insightFor(id:keyof Answers,a:Answers):string{
 if(id==="subjects"&&a.subjects.includes("computers"))return "You chose computers—here are several different routes, not just one degree.";
 if(id==="stream"&&a.stream==="science-maths")return "Science with Maths can keep engineering, computing and physical-science routes open, depending on exact eligibility.";
 if(id==="stream"&&a.stream==="commerce")return "Commerce can lead to accounting, finance, business, economics, analytics and professional qualifications.";
 if(id==="stage"&&a.stage==="after10")return "After Class 10, you can compare Class 11–12, diploma and ITI/vocational routes before deciding.";
 if(id==="interests"&&a.interests.includes("help"))return "Helping people can mean healthcare, teaching, psychology, social work, law or community work—each has different training.";
 if(id==="budget"&&a.budget==="low")return "We’ll prioritise lower-cost routes, public institutions and scholarships—not assume a private college is possible.";
 if(id==="confidence"&&a.confidence==="lost")return "Being unsure is a valid starting point. We’ll use small experiments and simple explanations, not pressure you to pick one career.";
 return "Your answer helps narrow the map—but it does not close off other possibilities.";
}
function explainFor(id:keyof Answers,a:Answers):string{
 if(id==="subjects"&&a.subjects.includes("computers"))return "Computer-related options include software development, IT infrastructure, data and AI, cybersecurity, electronics/embedded systems, design and business technology. Compare what each person does every day before choosing a course.";
 if(id==="stream"&&a.stream==="science-maths")return "A common engineering route is Class 11–12 with the required subjects → entrance/admission process → degree or diploma → projects/internships → applications. Other science routes also exist, so check prerequisites before choosing.";
 if(id==="stream"&&a.stream==="commerce")return "Possible routes include BCom/BBA/economics, accounting and finance, and professional qualifications such as CA, CS or CMA. Each has different exams, workload and job types.";
 if(id==="stage"&&a.stage==="after10")return "Class 11–12 is not the only option. A diploma or vocational route may fit some students better. We’ll compare cost, duration, subjects, future study and local admissions.";
 if(id==="location")return a.location?`We’ll use ${a.location} as the starting area for college research. We should verify distance, travel cost, current cutoffs and official placement reports rather than assume a college is best.`:"Enter a city or district so college research can be relevant to your area.";
 return "As you answer more questions, the route cards and explanations will change. You can click a route to inspect the course, exam routes, possible work and official sources.";
}
function dailyWork(p:Pathway):string{
 const s=(p.title+" "+p.field+" "+p.job_roles.join(" ")).toLowerCase();
 if(/computer|software|information technology|artificial intelligence|data|cyber/i.test(s))return "Depending on the role, a typical day may involve understanding a problem, writing or reviewing code, testing whether a feature works, finding bugs, reading documentation, discussing requirements with teammates, protecting data, or explaining results. Data and AI roles also involve cleaning messy data and checking whether conclusions are reliable. Entry-level jobs usually include learning an existing system—not inventing a whole app from scratch every day.";
 if(/civil|architecture|construction/i.test(s))return "Work can mix drawings and calculations with site visits, measurements, schedules, materials, safety checks and coordination with contractors or clients. Design roles spend more time on drawings and software; site roles spend more time outdoors and coordinating real construction. Deadlines, weather, safety and budgets affect the work.";
 if(/mechanical|electrical|electronics|robot|aerospace|manufacturing/i.test(s))return "Work may involve designing parts or circuits, checking specifications, using simulation tools, testing prototypes, analysing failures, documenting results and coordinating with manufacturing or service teams. Some jobs are desk-based design; others involve labs, factories, field visits or maintenance.";
 if(/commerce|account|finance|business|econom|management|bank/i.test(s))return "Work may include checking records, preparing reports, analysing numbers, following rules, explaining options to clients, tracking budgets, forecasting, or coordinating projects. Accuracy, ethics, deadlines and clear communication matter. A finance or accounting job is not automatically stock trading, and a business degree alone does not guarantee a management role.";
 if(/nurs|medicine|medical|pharmacy|physio|health|veterinary/i.test(s))return "Work depends on the profession and legal scope of practice. It may involve studying patient information, following safety and hygiene procedures, explaining options, documenting care, using specialised equipment and working with a team. Many health roles involve shifts, emotional demands and strict professional responsibilities; required degrees and registration must be checked carefully.";
 if(/design|fashion|animation|media|journal|creative|ux/i.test(s))return "Work usually starts by understanding the audience or brief, researching examples, making drafts or prototypes, collecting feedback, revising the work and presenting a final result. Creative careers are not only inspiration: they involve deadlines, software/tools, collaboration, criticism and a portfolio that shows how you think.";
 if(/law|psychology|social work|teaching|english|humanities/i.test(s))return "Work may involve reading and researching, listening carefully, preparing written material, explaining complex information, supporting people, planning sessions or lessons, maintaining records and following ethical rules. Some routes require postgraduate qualifications, supervised practice, licensing or competitive exams before independent professional work.";
 if(/agriculture|environment|animal|forestry/i.test(s))return "Work may combine field observations, sampling, data or records, equipment, environmental or animal-care procedures, reporting and communication with farmers, communities, organisations or regulators. The balance between outdoor and desk work varies greatly by employer and specialisation.";
 return `A real workday depends on the specific role. Possible roles include ${p.job_roles.slice(0,4).join(", ")}. In any role, expect a mix of learning the process, doing practical tasks, communicating with others, documenting work and improving from feedback. Ask a current student or professional what a normal week looks like.`;
}
function roadmapFor(p:Pathway):string[]{
 const s=(p.title+" "+p.field).toLowerCase();
 const entry=p.typical_entry;
 const base=[`Confirm the exact qualification and entry requirements for this route: ${entry}`,`Compare at least three recognised institutions or training providers. Check the syllabus, fees, travel/hostel cost, practical facilities and student support.`,`Apply through the official institution or counselling portal. Keep application numbers, documents and deadlines in one place.`,`During study, practise the core topics, complete small real projects/practical work, and ask for feedback.`,`Before graduating, prepare a CV/portfolio, practise role-specific interviews and apply to internships, apprenticeships or entry-level jobs.`,`After the first role, use work experience to specialise or pursue further qualifications if they are useful for the role you want.`];
 if(/computer|software|information technology|artificial intelligence|data|cyber/i.test(s))base[3]="Build foundations in programming, problem solving, databases and version control; make 2–3 small projects and explain how they work. For data/AI, include statistics and data-cleaning—not just AI-tool demos.";
 if(/commerce|finance|account|business|econom/i.test(s))base[3]="Build spreadsheet skills, written communication and numeracy; use realistic case studies and learn the tools and professional rules relevant to the job.";
 if(/design|fashion|animation|media/i.test(s))base[3]="Build a portfolio showing the problem, your process, drafts, feedback and final work—not only polished pictures.";
 return base;
}
function examGuide(p:Pathway):string{
 const s=(p.title+" "+p.field).toLowerCase();
 if(/btech|engineering|computer science|information technology|mechanical|civil|electronics|artificial intelligence/i.test(s))return "For many Indian undergraduate engineering routes, investigate JEE Main and your state/institution admission process (for Maharashtra, check the State CET Cell and the relevant MHT-CET rules). Diploma admission after Class 10 follows a different state process. The correct exam depends on the exact programme and college.";
 if(/medicine|mbbs|medical/i.test(s))return "For MBBS in India, NEET-UG is the key national entrance exam. Verify current eligibility, counselling and seat rules through the official exam and counselling authorities. Other health programmes can use different admission routes.";
 if(/law/i.test(s))return "Depending on the institution, investigate CLAT for participating national law universities, AILET for NLU Delhi, and each university’s own admission process. Five-year integrated law programmes and three-year LLB programmes have different eligibility.";
 if(/chartered account|accountancy|commerce|finance|company secretary|cma/i.test(s))return "Professional routes have their own staged registration and examinations. For CA, check ICAI; for Company Secretary, check ICSI; for Cost and Management Accountancy, check ICMAI. BCom/BBA admissions may instead depend on Class 12 marks, CUET or the university’s own process.";
 if(/architecture/i.test(s))return "For architecture, check the current NATA and/or JEE Main Paper 2 requirements for the specific programme and admission year, plus the official Council of Architecture and college rules.";
 if(/pharmacy/i.test(s))return "Pharmacy admission requirements vary by qualification and state. Check the current state admission authority, the relevant pharmacy regulator and the institution’s official eligibility notice.";
 if(/design|fashion|animation|product design|ux/i.test(s))return "Design admissions may involve UCEED, NID DAT, NIFT entrance processes or institution-specific tests/portfolios, depending on the programme. Do not assume one exam applies to all design courses.";
 if(/agriculture/i.test(s))return "Agriculture admissions may use CUET (ICAR route where applicable), state CETs or university-specific processes. Confirm the current-year rules for the exact programme.";
 return "There is no single exam for this whole field. Start from the exact course and institution, then verify its current-year official admission notice. Some routes use board marks, some use national/state exams, some require aptitude tests or portfolios, and some have professional exams after graduation.";
}
function examLinks(p:Pathway):[string,string][]{
 const s=(p.title+" "+p.field).toLowerCase();
 if(/btech|engineering|computer science|information technology|mechanical|civil|electronics|artificial intelligence/i.test(s))return [["JEE Main","https://jeemain.nta.nic.in/"],["Maharashtra CET Cell","https://cetcell.mahacet.org/"],["National Career Service","https://www.ncs.gov.in/"]];
 if(/medicine|mbbs|medical/i.test(s))return [["NEET-UG","https://neet.nta.nic.in/"],["National Medical Commission","https://www.nmc.org.in/"]];
 if(/law/i.test(s))return [["CLAT","https://consortiumofnlus.ac.in/"],["AILET","https://nationallawuniversitydelhi.in/"]];
 if(/chartered account/i.test(s))return [["ICAI","https://www.icai.org/"]];
 if(/company secretary/i.test(s))return [["ICSI","https://www.icsi.edu/"]];
 if(/cma|cost and management/i.test(s))return [["ICMAI","https://icmai.in/"]];
 if(/architecture/i.test(s))return [["NATA","https://www.nata.in/"],["JEE Main","https://jeemain.nta.nic.in/"],["Council of Architecture","https://www.coa.gov.in/"]];
 if(/design|fashion|animation|product design|ux/i.test(s))return [["UCEED","https://www.uceed.iitb.ac.in/"],["NID","https://admissions.nid.edu/"],["NIFT","https://www.nift.ac.in/"]];
 if(/agriculture/i.test(s))return [["ICAR","https://icar.org.in/"],["CUET","https://cuet.nta.nic.in/"]];
 return [["National Career Service","https://www.ncs.gov.in/"],["National Scholarship Portal","https://scholarships.gov.in/"]];
}
function skillPlan(p:Pathway):string[]{
 const s=(p.title+" "+p.field).toLowerCase();
 if(/computer|software|information technology|artificial intelligence|data|cyber/i.test(s))return ["Learn one programming language properly before jumping between tools.","Practise problem solving and learn Git/version control.","Build small projects and write a short explanation of each.","For data/AI, learn statistics, data cleaning and how to evaluate errors.","Read job descriptions for the exact role and note repeated skills."];
 if(/commerce|finance|account|business|econom/i.test(s))return ["Practise spreadsheets and basic data analysis.","Strengthen written and spoken communication.","Learn the relevant accounting, business or regulatory basics.","Use case studies or small projects to demonstrate judgement.","For regulated professions, follow the official qualification and exam pathway."];
 if(/design|fashion|animation|media/i.test(s))return ["Learn the main tools used in the specific field.","Make small projects with a clear brief and intended audience.","Show your process, drafts and how you used feedback.","Build a portfolio that fits the course or job requirements.","Practise presenting your choices and receiving critique."];
 return ["Build the core subject foundations needed for the course.","Try a small practical task, project, observation or volunteer experience.","Practise communication, teamwork and clear documentation.","Ask a current student or professional which tools and skills are used weekly.","Compare entry-level job descriptions and note the repeated requirements."];
}
function challengeFor(p:Pathway):string{
 const s=(p.title+" "+p.field).toLowerCase();
 if(/computer|software|data|artificial intelligence|cyber/i.test(s))return "You may spend hours debugging, reading documentation and learning new tools. Entry-level jobs are competitive in some markets; a degree alone may not be enough, so projects and fundamentals matter.";
 if(/civil|mechanical|electrical|engineering/i.test(s))return "Some roles involve demanding maths, lab work, site or factory conditions, safety responsibility, travel or project deadlines. Not every engineering graduate gets the same kind of job, and branch-specific outcomes should be checked.";
 if(/medicine|nursing|health/i.test(s))return "Training can be long and demanding, with exams, practical placements, shifts and responsibility for people’s wellbeing. Check the legal qualification and registration route before making plans.";
 if(/commerce|account|finance/i.test(s))return "Some routes have difficult staged exams, strict deadlines or repetitive accuracy-heavy work. A high salary is not guaranteed by the qualification; compare the actual roles you want.";
 if(/design|media|fashion/i.test(s))return "Deadlines, revisions and subjective feedback are common. Early work may be freelance or project-based in some areas, so portfolio quality, networking and financial planning can matter.";
 return "Every field has routine tasks and difficult periods, not just exciting highlights. Check the real course workload, job conditions, cost and typical entry-level roles before deciding.";
}

